insert into config (key,value) values ('provider_extractor_configs','{"cinecalidad":{"version":2,"mode":"pipeline","preset":"vimeos_json","steps":[{"id":"api_playback","action":"http_request","movie_url":"https://tmdb.allcalidad.re/v1/playback/movie/{id}","tv_url":"https://tmdb.allcalidad.re/v1/playback/tvshow/{id}?season={s}&episode={e}","method":"GET","headers":{"Referer":"https://cinecalidad.am/","User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"},"response_type":"json","timeout_ms":7000},{"id":"vimeos_embed","action":"find_in_array","input":"{{api_playback.embeds}}","match":{"url_contains":"vimeos"},"select":"url"},{"id":"vimeos_html","action":"http_request","url":"{{vimeos_embed}}","method":"GET","headers":{"Referer":"https://cinecalidad.am/","User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"},"response_type":"text","timeout_ms":7000},{"id":"unpacked_js","action":"unpack_packer","input":"{{vimeos_html}}"},{"id":"hls_stream","action":"regex_extract","input":"{{unpacked_js}}","pattern":"https?:\\\\/\\\\/[^\\\\s\\\"\\x27]+\\\\.m3u8[^\\\\s\\\"\\x27]*","group":0},{"id":"subtitles","action":"extract_subtitles_vimeos","input":"{{unpacked_js}}","required":false}],"output":{"hlsUrl":"{{hls_stream}}","backupHlsUrls":[],"subtitles":"{{subtitles}}","embeds":"{{api_playback.embeds}}"}},"nasriplay":{"version":2,"mode":"pipeline","preset":"nasriplay_token","steps":[{"id":"embed_page","action":"http_request","movie_url":"https://nsrplay.space/embed/movie/{id}","tv_url":"https://nsrplay.space/embed/tv/{id}/{s}/{e}","method":"GET","headers":{"User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"},"response_type":"text","timeout_ms":7000},{"id":"page_token","action":"regex_extract","input":"{{embed_page}}","pattern":"PAGE_TOKEN\\\\s*=\\\\s*[\\\"\\x27]([^\\\"\\x27]+)[\\\"\\x27]","group":1},{"id":"sources_api","action":"http_request","movie_url":"https://nsrplay.space/api/v1/embed/sources/movie/{id}?pt={{page_token}}","tv_url":"https://nsrplay.space/api/v1/embed/sources/tv/{id}/{s}/{e}?pt={{page_token}}","method":"GET","headers":{"User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36","Referer":"https://nsrplay.space/embed/movie/{id}"},"response_type":"json","timeout_ms":7000},{"id":"nasri_streams","action":"nasriplay_resolve_servers","input":"{{sources_api.servers}}"}],"output":{"hlsUrl":"{{nasri_streams.hlsUrl}}","backupHlsUrls":"{{nasri_streams.backupHlsUrls}}","embeds":"{{nasri_streams.embeds}}"}},"playerflix":{"version":2,"mode":"pipeline","preset":"playerflix","steps":[{"id":"playerflix_stream","action":"extract_playerflix"}],"output":{"hlsUrl":"{{playerflix_stream.hlsUrl}}","backupHlsUrls":"{{playerflix_stream.backupHlsUrls}}"}},"megaembed":{"version":2,"mode":"pipeline","preset":"megaembed","steps":[{"id":"embed_page","action":"http_request","movie_url":"https://mgeb.top/embed/{id}","tv_url":"https://mgeb.top/embed/{id}/{s}/{e}","method":"GET","headers":{"User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"},"response_type":"text","timeout_ms":15000},{"id":"sources_json","action":"regex_extract","input":"{{embed_page}}","pattern":"var\\\\s+sources\\\\s*=\\\\s*(\\\\[[\\\\s\\\\S]*?\\\\]);","group":1},{"id":"mega_streams","action":"megaembed_parse_sources","input":"{{sources_json}}"}],"output":{"hlsUrl":"{{mega_streams.hlsUrl}}","backupHlsUrls":"{{mega_streams.backupHlsUrls}}"}},"watchplay":{"version":2,"mode":"pipeline","preset":"watchplay","steps":[{"id":"watchplay_stream","action":"extract_watchplay","movie_url":"https://v2.watchplay.shop/movie/{id}","tv_url":"https://v2.watchplay.shop/tvshow/{id}/{s}/{e}"}],"output":{"hlsUrl":"{{watchplay_stream.hlsUrl}}","backupHlsUrls":"{{watchplay_stream.backupHlsUrls}}"}} }') on conflict (key) do update set value=excluded.value;
